def bi(en,ko,tag='span'): return f'<{tag} class=" l-en">{e(en)}</{tag}><{tag} class=" l-ko">{e(ko)}</{tag}>'
def card(t,s,w,meta,url):
    return (f'<article class="card ecard"><div class="body">{bi(*t,tag="h3")}<div class="sum"><p class="en">{e(s[0])}</p><p class="kot">{e(s[1])}</p></div>'
            f'<p class="ko"><b>↳</b>{bi(*w)}</p><span class="meta">{e(meta)}</span><a class="read" href="{e(url)}" target="_blank" rel="noopener">Read the article / 원문 기사 보기 ↗</a></div></article>')
def sec(en,ko,inner,note=''): return f'<section><div class="sh"><h2>{e(en)}</h2><small>{e(ko)}</small></div>{inner}{note}</section>'
